async function main() {
  for (const [slug, questions] of Object.entries(quizQuestions)) {
    const quiz = await prisma.quiz.findUnique({ where: { slug } });
    if (!quiz) { console.log('Quiz not found:', slug); continue; }
    
    const created = await prisma.quizQuestion.createMany({
      data: questions.map(q => ({ ...q, quizId: quiz.id })),
    });
    console.log(`Created ${created.count} questions for ${slug}`);
  }
  
  console.log('Done! Total questions:', await prisma.quizQuestion.count());
}

main().catch(console.error).finally(() => prisma.$disconnect());
